function Get-UndiesRecoveryCheckpoint { param([string]$Root=(Get-Location).Path,[string]$SessionId) $p=Join-Path $Root ".undies/recovery/$SessionId.checkpoint.json"; if(Test-Path -LiteralPath $p){ return Read-UndiesJson $p }; return $null }
function Save-UndiesRecoveryCheckpoint { param([string]$Root=(Get-Location).Path,[string]$SessionId,[string]$ModuleId,[string]$Checkpoint,$Queue) $data=[ordered]@{ session_id=$SessionId; module_id=$ModuleId; checkpoint=$Checkpoint; saved_local=Get-UndiesCentralTime; saved_utc=Get-UndiesUtcTime; completed_modules=@($Queue.completed); pending_modules=@($Queue.pending); stopped_modules=@($Queue.stopped); queue=$Queue }; Save-UndiesJsonAtomic -Path (Join-Path $Root ".undies/recovery/$SessionId.checkpoint.json") -Data $data; return $data }
function Test-UndiesRecoveryState { param([string]$Root=(Get-Location).Path,[string]$SessionId) try { $cp=Get-UndiesRecoveryCheckpoint -Root $Root -SessionId $SessionId; if(-not $cp){ return [pscustomobject]@{ status='YELLOW'; reason='No checkpoint exists yet.' } }; return [pscustomobject]@{ status='GREEN'; reason='Checkpoint readable'; checkpoint=$cp.checkpoint; module_id=$cp.module_id; completed_modules=$cp.completed_modules; pending_modules=$cp.pending_modules } } catch { return [pscustomobject]@{ status='RED'; reason='Corrupt recovery data fails closed: '+$_.Exception.Message; repair_instruction='Preserve evidence, move the corrupt checkpoint aside only after review, then resume from the last valid session report.' } } }
